import csv,collections
r=list(csv.DictReader(open('model/bq_fin_LLM.csv')))
np_y=collections.defaultdict(float);rv=collections.defaultdict(float);dv={}
for x in r:
  q=x.get('quarter') or '';y=q[:4]
  try: np_y[y]+=float(x['np']); rv[y]+=float(x['rev'])
  except: pass
  if q.endswith('Q4'): dv[y]=x.get('div1y')
for y in sorted(np_y): print(y, round(np_y[y],1), round(rv[y],1), dv.get(y))
"; grep -n -i "31,7\|31.7\|tăng vốn\|tang von\|phát hành" REPORT_rev4.md REPORT.md model/assumptions_LLM_20261123_rev5.json | head -20

